In this loop:
```C++
JPH::JobHandle JoltJobSystem::CreateJob(const char *p_name, JPH::ColorArg p_color, const JPH::JobSystem::JobFunction &p_job_function, JPH::uint32 p_dependency_count) {
	Job *job = nullptr;

	while (true) {
		JPH::uint32 job_index = jobs.ConstructObject(p_name, p_color, this, p_job_function, p_dependency_count);

		if (job_index != JPH::FixedSizeFreeList<Job>::cInvalidObjectIndex) {
			job = &jobs.Get(job_index);
			break;
		}

		WARN_PRINT_ONCE("Jolt Physics job system exceeded the maximum number of jobs. This should not happen. Please report this. Waiting for jobs to become available...");

		OS::get_singleton()->delay_usec(100);

		_reclaim_jobs();
	}
```

A worker thread is in this loop from the PR, so I think it's related:

```C++
	if (wait) {
		// There are a couple of reasons why we got here:
		// 1) We re-started the task in _load_complete_inner but we also
		//    got started via the original task in the WorkerThreadPool
		// 2) There's a race between multiple threads in _load_complete_inner
		//    and more than one thread thought they had to restart
		//
		// This task was already running, wait for the other thread to complete.
		ThreadLoadStatus status;
		do {
			OS::get_singleton()->delay_usec(1000);
			thread_load_mutex.lock();
			status = load_task.status;
			thread_load_mutex.unlock();
		} while (status == THREAD_LOAD_IN_PROGRESS);

		load_task.load_token->unreference();
		return;
	}
```

### Steps to reproduce

In short, you need to call ResourceLoader.load_threaded_request() and ResourceLoader.load_threaded_get_status() (not sure if the get status is even needed or if you just need to do the load request).

Here's the relevant code from my larger project:

```gdscript
const USE_THREADED_LOADING := true


func _process(delta : float):
	match level_state:
		LevelState.PLAYING:
			level_time += delta
		LevelState.INTERMISSION:
			pass # Now handled in the ui_system.
		LevelState.LOADING:
			process_loading(delta)


func process_loading(_delta : float) -> void:
	if (USE_THREADED_LOADING):
		var percent : Array
		var status := ResourceLoader.load_threaded_get_status(loading_level_path, percent)
		match status:
			ResourceLoader.ThreadLoadStatus.THREAD_LOAD_FAILED:
				breakpoint
				MessageSystem.center_message(null, "Load failed!")
			ResourceLoader.ThreadLoadStatus.THREAD_LOAD_INVALID_RESOURCE:
	#			breakpoint
				MessageSystem.center_message(null, "Invalid resousrce!")
			ResourceLoader.ThreadLoadStatus.THREAD_LOAD_IN_PROGRESS:
				UISystem.update_loading_screen_fraction(percent[0])
				#MessageSystem.center_message(null, str("Loading: ", floorf(percent[0] * 100.0), "%"))
			ResourceLoader.ThreadLoadStatus.THREAD_LOAD_LOADED:
				var resource := ResourceLoader.load_threaded_get(loading_level_path)
				assert(resource)
				level_resource_loaded(resource)

func load_level(level_name : String, from_save_or_recording := false) -> bool:
	frames_loading = 0
	loaded_from_save_or_recording = from_save_or_recording
	if (level_name.length() == 0):
		return false
	reset_inventory = false # Might load a level that doesn't have a level.gd script, so default this back to false
	HUDSystem.show(true)
	MenuSystem.in_title_screen = false
	MenuSystem.close_menu()
	loading_level_path = "res://levels/%s.tscn" % level_name
	if (!ResourceLoader.exists(loading_level_path)):
		print(loading_level_path, " does not exist.")
		Console.print_line("%s does not exist." % loading_level_path)
		breakpoint
		return false
	if (USE_THREADED_LOADING):
		var request_response := ResourceLoader.load_threaded_request(loading_level_path, "", true)
		if (request_response == OK):
			SaveSystem.completed_levels_time += level_time
			level_state = LevelState.LOADING
			current_level_name = level_name
			UISystem.show_loading_screen(true)
			UISystem.update_loading_screen_fraction(0.0)
			return true
```



### Minimal reproduction project (MRP)

Requires a pretty complex scene to repro.  I'll see if I can make something simpler later.  Also doesn't repro 100% of the time and I think is more likely to happen with slower storage hardware, such as magnetic drives.
